\usetikzlibrary{calc,angles,quotes}
\begin{tikzpicture}[x=1cm,y=1cm,draw=black,text=black,line width=0.8pt,every node/.style={font=\fontsize{10}{12}\selectfont}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (A) at (0,0);
\coordinate (B) at (8,0);
\coordinate (C) at (2,2);
\pgfmathsetmacro{\aa}{sqrt(40)}
\pgfmathsetmacro{\bb}{sqrt(8)}
\pgfmathsetmacro{\ss}{\aa+\bb+8}
\pgfmathsetmacro{\ix}{(8*\bb+16)/\ss}
\pgfmathsetmacro{\rr}{16/\ss}
\coordinate (I) at (\ix,\rr);
\coordinate (T) at (\ix,0);
\coordinate (D) at ({8+(2-8)*8/(8+\bb)},{2*8/(8+\bb)});
\coordinate (E) at ({2*8/(8+\aa)},{2*8/(8+\aa)});
\coordinate (F) at ({8*\bb/(\aa+\bb)},0);
\draw (A)--(B)--(C)--cycle;
\draw[line width=0.4pt,dashed] (A)--(D) (B)--(E) (C)--(F);
\draw (I) circle[radius=\rr];
\draw[line width=0.4pt] (I)--(T);
\draw[line width=0.4pt] ($(T)+(0,0.18)$)--($(T)+(0.18,0.18)$)--($(T)+(0.18,0)$);
\fill (I) circle[radius=1pt];
\node[below left] at (A) {$A$};
\node[below right] at (B) {$B$};
\node[above] at (C) {$C$};
\node[right=3pt] at (I) {$I$};
\node[below] at (T) {$T$};
\end{tikzpicture}
